const ROOT=document.querySelector('#app');
const S={allowDemo:false,me:null,page:'home',filter:'All',search:'',friendTab:'friends',borrowTab:'requests',notifyTab:'notifications',friends:null,wardrobe:[],outfits:[],notifications:[],activity:null,friendCloset:null,friendId:null,modal:null,detail:null,editing:false,editor:null,studioTab:'mine',studioFriendId:null,studioFriendItems:[],previews:{},authMode:'login',health:null};
const ICON={home:'<path d="m3 10 9-7 9 7v11H3z"/><path d="M9 21v-8h6v8"/>',shirt:'<path d="m16 3 5 4-3 5-3-2v11H9V10l-3 2-3-5 5-4 4 3z"/>',hanger:'<path d="M12 7a2 2 0 1 0-2-2"/><path d="M12 7v3L3 16a2 2 0 0 0 1 4h16a2 2 0 0 0 1-4l-9-6"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3"/><path d="M17 4a4 4 0 0 1 0 8m1 2a6 6 0 0 1 4 6v1"/>',box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 5 9-5M12 12v10"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 10h18c0-2-3-3-3-10M10 22h4"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16.5 16.5 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="m4 20 4-.5L20 7l-3-3L5 16z"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',back:'<path d="M20 12H4m7 7-7-7 7-7"/>',check:'<path d="m4 12 5 5L20 6"/>',x:'<path d="M5 5l14 14M19 5 5 19"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',layers:'<path d="m2 9 10-6 10 6-10 6zM2 15l10 6 10-6"/>',up:'<path d="M12 21V3m-6 6 6-6 6 6"/>',down:'<path d="M12 3v18m-6-6 6 6 6-6"/>',save:'<path d="M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 18 6-6 4 3 4-5 4 6"/>',logout:'<path d="M12 3H4v18h8m1-5 5-4-5-4m5 4H9"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',return:'<path d="M3 12a9 9 0 1 0 3-7M3 3v6h6"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',heart:'<path d="M20 6c-3-4-8-2-8 1-1-4-6-5-9-1-4 6 9 15 9 15S24 12 20 6z"/>'};
const ico=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[name]||ICON.image}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=x=>esc(x).replaceAll('\n','<br>');
const niceDate=d=>{try{return new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}catch{return ''}};
const urlItem=i=>i?.image_path||'/assets/cream-cardigan.png';
function avatar(u,size='mid'){return `<div class="avatar ${size}">${u?.avatar_path?`<img src="${esc(u.avatar_path)}" alt="">`:esc((u?.display_name||u?.username||'?')[0]?.toUpperCase())}</div>`}
function badge(status,holder){const m={available:['Available','green'],reserved:['Reserved','amber'],borrowed:[`With ${holder||'borrower'}`,'pink'],pending:['Pending','amber'],approved:['Awaiting Handover','blue'],return_requested:['Return Requested','amber'],returned:['Returned','green'],rejected:['Rejected','pink'],cancelled:['Cancelled','pink']};let a=m[status]||[status,'blue'];return `<span class="badge ${a[1]}">${esc(a[0])}</span>`}
const btn=(label,action,id='',kind='secondary',extra='')=>`<button class="btn ${kind} ${extra}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
async function api(path,{method='GET',body=null,form=false}={}){
 const o={method,credentials:'same-origin',headers:{}};if(body!==null){o.body=form?body:JSON.stringify(body);if(!form)o.headers['Content-Type']='application/json'}
 let response;try{response=await fetch('/api'+path,o)}catch{throw new Error('Could not reach the server')}
 let d;try{d=await response.json()}catch{throw new Error('Unexpected server response')}
 if(!response.ok){let err=new Error(d.error||'Request failed');err.status=response.status;throw err}
 return d;
}
function toast(msg,bad=false){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast'+(bad?' error':'');d.textContent=msg;document.body.append(d);setTimeout(()=>d.remove(),4300)}
async function run(fn){try{await fn()}catch(err){toast(err.message||String(err),true);console.error(err)}}
function navigate(path){history.pushState({},'',path);route()}
function getRoute(){const p=location.pathname.split('/').filter(Boolean);return {page:p[0]||'home',id:p[1]||null}}
async function route(){const r=getRoute();S.page=r.page;S.friendId=r.id;S.modal=null;S.search='';S.filter='All';
 if(!S.me){render();return}
 try{
  if(r.page==='home'){const [w,o,n]=await Promise.all([api('/wardrobe'),api('/ootds'),api('/notifications')]);S.wardrobe=w.items;S.outfits=o.ootds;S.notifications=n.notifications}
  if(r.page==='wardrobe')S.wardrobe=(await api('/wardrobe')).items;
  if(r.page==='ootd')S.outfits=(await api('/ootds')).ootds;
  if(r.page==='studio'){
   const [w,f,o]=await Promise.all([api('/wardrobe'),api('/friends'),api('/ootds')]);S.wardrobe=w.items;S.friends=f;S.outfits=o.ootds;
   const existing=o.ootds.find(x=>x.id===r.id);
   if(r.id&&!existing){toast('OOTD not found',true);navigate('/ootd');return}
   S.editor={id:existing?.id||null,title:existing?.title||'',items:existing?existing.items.map(x=>({...x})):[],selected:-1};
   if(S.pendingItem){addCanvasItem(S.pendingItem);S.pendingItem=null}
   S.studioTab='mine';S.studioFriendId=null;S.studioFriendItems=[];
  }
  if(r.page==='friends'){if(!['friends','incoming','outgoing'].includes(S.friendTab))S.friendTab='friends';S.friends=await api('/friends');S.previews={};const first=S.friends.friends.slice(0,8);await Promise.all(first.map(async f=>{try{S.previews[f.id]=(await api(`/friends/${f.id}/closet`)).items.slice(0,3)}catch{}}))}
  if(r.page==='friend')S.friendCloset=await api(`/friends/${r.id}/closet`);
  if(r.page==='borrowing')S.borrow=(await api('/borrowing')).requests;
  if(r.page==='notifications'){const [n,a]=await Promise.all([api('/notifications'),api('/activity')]);S.notifications=n.notifications;S.activity=a}
  if(r.page==='profile')S.me=await api('/me');
  render();window.scrollTo(0,0);
 }catch(err){if(err.status===401){S.me=null;render()}else{toast(err.message,true);render()}}
}
function render(){if(!S.me){ROOT.innerHTML=renderAuth();return}ROOT.innerHTML=`<div class="app-shell">${topbar()}<main class="page">${renderPage()}</main><footer class="footer">Pieces, patterns, and shared wardrobes · WardrobeShare</footer></div>${S.modal?renderModal():''}`}
function topbar(){const nav=[['home','Home','home'],['wardrobe','My Wardrobe','shirt'],['ootd','OOTD','hanger'],['friends','Friends','users'],['borrowing','Borrowing','box']];let active=S.page==='studio'?'ootd':S.page==='friend'?'friends':S.page;const unread=(S.notifications||[]).filter(n=>!n.read).length;
 return `<header class="topbar"><a href="/home" data-link class="logo"><span class="brand-script">WardrobeShare</span><span class="brand-atelier">CLOTHING JOURNAL</span></a><nav class="nav">${nav.map(([id,label,i])=>`<a href="/${id}" data-link class="nav-link ${active===id?'active':''}">${ico(i)}${label}</a>`).join('')}</nav><div class="top-right"><button class="top-icon mobile-menu" data-action="mobileMenu" aria-label="Menu">☰</button><button class="top-icon" data-action="goNotifications" aria-label="Notifications">${ico('bell',23)}${unread?'<span class="dot"></span>':''}</button><button class="top-icon" data-action="goProfile" aria-label="Profile">${avatar(S.me,'small')}</button></div></header>`}
function renderPage(){return ({home:pageHome,wardrobe:pageWardrobe,ootd:pageOOTD,studio:pageStudio,friends:pageFriends,friend:pageFriend,borrowing:pageBorrowing,notifications:pageNotifications,profile:pageProfile}[S.page]||pageHome)()}
function renderAuth(){const registering=S.authMode==='register';return `<div class="auth-wrap"><div class="auth-art"><div class="brand-script">WardrobeShare</div><div class="scribble">A little closet,<br>a lot of <em>possibilities.</em></div><p>Collect pieces you love, build your looks like a scrapbook, and share your closet with your favorite people.</p><div class="auth-images"><img src="/assets/cream-cardigan.png"><img src="/assets/brown-skirt.png"><img src="/assets/mary-janes.png"></div></div><div class="auth-box"><span class="badge pink" style="width:max-content;margin-bottom:16px">♡ your social wardrobe</span><h1>${registering?'Join the closet':'Welcome back'}</h1><p class="muted" style="margin-top:9px">${registering?'Create an account to start styling together.':'Sign in to see your clothes, friends and OOTDs.'}</p><form id="auth-form">${registering?'<div class="field"><label>Display name</label><input class="input" name="display_name" placeholder="Your name" required></div>':''}<div class="field"><label>${registering?'Username':'Username or email'}</label><input class="input" name="username" placeholder="@username" required></div>${registering?'<div class="field"><label>Email</label><input class="input" type="email" name="email" placeholder="you@example.com" required></div>':''}<div class="field"><label>Password</label><input class="input" name="password" type="password" minlength="8" placeholder="At least 8 characters" required></div><button class="btn primary big" type="submit" style="width:100%">${registering?'Create Account':'Log In'} ${ico('arrow')}</button></form><p class="switch">${registering?'Already have an account?':'New to WardrobeShare?'} <button data-action="authSwitch">${registering?'Log in':'Sign up'}</button></p><div class="divider"></div>${S.allowDemo?`<div class="note sage"><strong>Try the demo:</strong> username <code>taa</code> · password <code>demo12345</code><br>Demo accounts May and June use the same password. Data persists locally.</div>${btn('Enter Demo as Taa','demoLogin','','secondary','big')}`:''}<p class="muted" style="font-size:11px;margin-top:15px">Self-hosted · Photos stay on your server · No third-party login</p></div></div>`}
function pageHome(){let outfits=S.outfits.slice(0,4),clothes=S.wardrobe.slice(0,6);return `<div class="hero"><div class="copy"><small>THE SHARED WARDROBE · VOL. 01</small><h1>Welcome back,<br><em>${esc(S.me.display_name)}!</em></h1><p>Plan your outfits, collect your favorite pieces, and mix your wardrobe with your friends — one sticker at a time.</p><div class="hero-actions">${btn(ico('plus')+' Create OOTD','newOOTD','','primary')}${btn(ico('camera')+' Add Clothing','openAdd','','secondary')}${btn(ico('users')+' Explore Friends','goFriends','','secondary')}</div></div><div class="hero-collage"><img src="/assets/cream-cardigan.png" alt="cardigan"><img src="/assets/brown-skirt.png" alt="skirt"><img src="/assets/mary-janes.png" alt="shoes"><span class="fabric-tab" aria-hidden="true"></span></div></div><section class="section"><div class="section-head"><div><h2>My Recent OOTD</h2><p class="subline">Little combinations saved for later</p></div><a href="/ootd" data-link>View All OOTD →</a></div><div class="outfit-grid">${outfits.map(outfit=>outfitCard(outfit,false)).join('')}${!outfits.length?`<div class="empty">Create your first OOTD</div>`:''}<div class="paper" style="display:grid;place-content:center;min-height:230px;text-align:center;gap:13px;cursor:pointer" data-action="newOOTD"><div style="font-size:32px;color:#987354">＋</div><strong>Create New OOTD</strong></div></div></section><section class="section"><div class="section-head"><div><h2>Recently Added Clothes</h2><p class="subline">Fresh favorites in your wardrobe</p></div><a href="/wardrobe" data-link>View Wardrobe →</a></div><div class="sticker-strip">${clothes.map(i=>`<a class="sticker-mini" href="/wardrobe" data-link><img src="${esc(urlItem(i))}" alt="${esc(i.name)}"><span>${esc(i.name)}</span></a>`).join('')}</div></section>`}
function outfitPreview(o,interactive=false){return `<div class="preview">${(o.items||[]).map((it,index)=>it.image_path?`<img class="preview-cutout" src="${esc(it.image_path)}" alt="${esc(it.name)}" ${interactive?`data-action="selectOutfitItem" data-id="${index}" style="cursor:pointer;pointer-events:auto;left:${it.x*100}%;top:${it.y*100}%;width:${it.w*100}%;z-index:${it.z||1}"`:`style="left:${it.x*100}%;top:${it.y*100}%;width:${it.w*100}%;z-index:${it.z||1}"`}>`:'').join('')}</div>`}
function outfitCard(o,friend=false){return `<div class="outfit-card paper"><div data-action="${friend?'showFriendOutfit':'showOutfit'}" data-id="${esc(o.id)}" style="cursor:pointer" title="View outfit and original clothing owners">${outfitPreview(o)}</div><div class="outfit-info"><div style="flex:1;min-width:0"><div class="name">${esc(o.title)}</div><p class="date">${niceDate(o.updated_at)} · ${o.item_count} pieces</p></div><div class="tools">${friend?btn(ico('image'),'showFriendOutfit',o.id,'ghost','small'):btn(ico('edit'),'editOOTD',o.id,'ghost','small')}${friend?'':btn(ico('trash'),'deleteOOTD',o.id,'ghost','small')}</div></div></div>`}
function categoryTabs(items,active=S.filter){let cats=['All',...new Set(items.map(i=>i.category).filter(Boolean))];return `<div class="pill-tabs">${cats.map(c=>`<button class="pill ${c===active?'active':''}" data-action="filter" data-id="${esc(c)}">${esc(c)}</button>`).join('')}</div>`}
function matches(item){return(S.filter==='All'||item.category===S.filter)&&(!S.search||(item.name+' '+item.color+' '+item.category).toLowerCase().includes(S.search.toLowerCase()))}
function pageWardrobe(){let items=S.wardrobe.filter(matches);return `<div class="heading-line"><div><h1 class="tag-paper">My Wardrobe</h1><p>My little closet · ${S.wardrobe.length} pieces</p></div><div class="heading-right">${btn(ico('plus')+' Add Clothing','openAdd','','primary','big')}</div></div><div class="page-toolbar"><div class="search"><span>${ico('search')}</span><input class="input" id="wardrobe-search" placeholder="Search your clothes..." value="${esc(S.search)}"></div>${categoryTabs(S.wardrobe)}</div>${items.length?`<div class="closet-grid">${items.map(item=>clothingCard(item,false)).join('')}</div>`:empty('No clothes found','Add your first piece or try another filter.','openAdd','Add Clothing')}`}
function clothingCard(i,friend=false){return `<div class="clothing-card" data-action="${friend?'friendItem':'openClothing'}" data-id="${esc(i.id)}"><div class="photo"><img src="${esc(urlItem(i))}" alt="${esc(i.name)}"><span class="card-button" aria-hidden="true"></span></div><div class="clothing-title">${esc(i.name)}</div><div class="meta"><span>${esc(i.color||i.category)}</span><span>${esc(i.category)}</span></div>${badge(i.state,i.holder)}<div class="mini-actions">${friend?`${btn(ico('plus')+' OOTD','addFriendToOOTD',i.id,'soft','tiny')}${btn('Borrow','requestBorrow',i.id,'secondary','tiny')}`:`${btn(ico('plus')+' OOTD','addOwnToOOTD',i.id,'soft','tiny')}${btn(ico('edit')+' Edit','editClothing',i.id,'secondary','tiny')}${btn(ico('trash')+' Delete','deleteClothing',i.id,'secondary','tiny')}`}</div></div>`}
const empty=(title,desc,action,label)=>`<div class="empty"><span class="empty-button" aria-hidden="true"></span><h3>${title}</h3><p style="margin:10px 0 16px">${desc}</p>${action?btn(label,action,'','primary'):''}</div>`;
function pageOOTD(){let found=S.outfits.filter(o=>o.title.toLowerCase().includes(S.search.toLowerCase()));return `<div class="heading-line gallery-head"><div><h1 class="tag-paper">My OOTD</h1><p>Your saved outfit combinations · ${S.outfits.length} slots</p></div><div class="heading-right">${btn(ico('plus')+' New OOTD','newOOTD','','primary','big')}</div></div><div class="page-toolbar"><div class="search"><span>${ico('search')}</span><input id="ootd-search" class="input" placeholder="Search your OOTD..." value="${esc(S.search)}"></div><span class="badge pink">Outfit collection</span></div>${found.length?`<div class="outfit-grid">${found.map(o=>outfitCard(o)).join('')}</div>`:empty('Your OOTD gallery is waiting','Drag clothes together and save your first look.','newOOTD','Create OOTD')}`}
function libraryItems(){return S.studioTab==='mine'?S.wardrobe:S.studioFriendItems}
function pageStudio(){let e=S.editor;if(!e)return empty('Loading editor…','');let items=libraryItems().filter(i=>(S.filter==='All'||i.category===S.filter)&&(!S.search||i.name.toLowerCase().includes(S.search.toLowerCase())));let selected=e.items[e.selected];let detail=selected?[...S.wardrobe,...S.studioFriendItems].find(i=>i.id===selected.item_id):null;
 return `<div class="heading-line"><div><h1 class="tag-paper">OOTD Studio</h1><p>Pick, layer, drag and arrange your pieces like fabric cutouts.</p></div><div class="heading-right" style="display:flex;gap:9px">${btn('← Gallery','goOOTD','','secondary')}${btn(ico('save')+' Save OOTD','saveOOTD','','primary')}</div></div><div class="editor-layout"><aside class="editor-panel"><div class="pill-tabs" style="margin-bottom:12px">${btn('My Wardrobe','studioMine','',''+(S.studioTab==='mine'?'primary':'secondary'),'small')}${btn('Friends','studioFriends','',''+(S.studioTab==='friends'?'primary':'secondary'),'small')}</div>${S.studioTab==='friends'?`<select class="input" id="studio-friend" style="margin-bottom:10px"><option value="">Choose a friend...</option>${(S.friends?.friends||[]).map(f=>`<option value="${f.id}" ${S.studioFriendId===f.id?'selected':''}>${esc(f.display_name)}</option>`).join('')}</select>`:''}<div class="search" style="margin-bottom:10px">${ico('search')}<input id="library-search" class="input" placeholder="Search clothing..." value="${esc(S.search)}"></div><select class="input" id="library-category" style="margin-bottom:12px"><option>All</option>${[...new Set(libraryItems().map(i=>i.category))].map(c=>`<option ${S.filter===c?'selected':''}>${esc(c)}</option>`).join('')}</select><div class="editor-library"><div class="library-grid">${items.map(i=>`<button class="library-item" data-action="putItem" data-id="${esc(i.id)}" title="Add ${esc(i.name)} to canvas"><img src="${esc(urlItem(i))}"><span>${esc(i.name)}</span></button>`).join('')}</div>${!items.length?`<p class="muted" style="padding:14px;font-size:12px">${S.studioTab==='friends'?'Choose a friend to add their pieces':'No matching clothes'}</p>`:''}</div></aside><div class="editor-canvas-wrap"><div class="editor-canvas" id="editor-canvas">${e.items.map((item,index)=>{const i=[...S.wardrobe,...S.studioFriendItems].find(p=>p.id===item.item_id)||item;return item.image_path||i.image_path?`<div class="editor-object ${e.selected===index?'selected':''}" data-index="${index}" style="left:${item.x*100}%;top:${item.y*100}%;width:${item.w*100}%;z-index:${item.z}"><img draggable="false" src="${esc(item.image_path||i.image_path)}" alt="${esc(i.name||'Item')}">${e.selected===index?'<span class="handle"></span>':''}</div>`:''}).join('')}${!e.items.length?'<div style="position:absolute;inset:0;display:grid;place-content:center;text-align:center;color:#9a8574;pointer-events:none"><div style="font-family:Georgia;font-size:35px">Your blank canvas</div><div style="margin-top:10px;font-size:13px">Click clothes on the left to start styling</div></div>':''}</div><div class="editor-caption">Drag to move · Select an item to resize or change its layer · No mannequin, no snapping</div></div><aside class="editor-panel"><h3>Outfit Details</h3><div class="field" style="margin-bottom:16px"><label>OOTD Title *</label><input id="editor-title" class="input" maxlength="80" placeholder="e.g. Café Day" value="${esc(e.title)}"></div><div class="divider"></div><h3>Selected Item</h3>${selected?`<img class="inspector-img" src="${esc(detail?.image_path||selected.image_path||'')}" alt=""><strong>${esc(detail?.name||selected.name||'Item')}</strong><p style="font-size:12px;margin:8px 0 15px;color:#846b58">Owner: ${esc(detail?.owner||selected.owner_name||'Friend')}</p><div class="note" style="margin-bottom:15px">Outfit planning only — this does not borrow or transfer clothing.</div><div class="field"><label>Size: <span id="size-percent">${Math.round(selected.w*100)}%</span></label><input type="range" class="range" id="item-size" min="8" max="95" value="${Math.round(selected.w*100)}"></div><div class="divider"></div><label class="muted" style="font-size:12px">Layer order</label><div class="inspector-buttons" style="margin-top:9px">${btn(ico('up')+' Forward','layerForward','','secondary','small')}${btn(ico('down')+' Backward','layerBackward','','secondary','small')}</div><div class="divider"></div>${btn(ico('trash')+' Remove from canvas','removeCanvas','','danger')}`:'<p class="muted" style="font-size:13px;line-height:1.7">Click an item on the canvas to see its name, owner, and editing controls.</p>'}<div class="divider"></div><p class="muted" style="font-size:12px">${e.items.length} pieces in current outfit</p></aside></div>`}
function pageFriends(){let f=S.friends||{friends:[],incoming:[],outgoing:[]};let list=f[S.friendTab]||[];return `<div class="heading-line"><div><h1 class="tag-paper">Friends</h1><p>Find your people, share your closet</p></div><div class="heading-right">${btn(ico('plus')+' Add Friend','openAddFriend','','primary')}</div></div><div class="page-toolbar"><div class="search" style="max-width:620px;width:100%">${ico('search')}<input id="friend-search" class="input" placeholder="Search username to add a friend..."></div>${btn('Search','searchFriend','','secondary')}</div><div class="pill-tabs" style="margin:0 0 18px">${[['friends','My Friends',f.friends.length],['incoming','Incoming Requests',f.incoming.length],['outgoing','Sent Requests',f.outgoing.length]].map(([k,label,n])=>`<button class="pill ${S.friendTab===k?'active':''}" data-action="friendTab" data-id="${k}">${label} (${n})</button>`).join('')}</div>${list.length?`<div class="people-grid">${list.map(friendCard).join('')}</div>`:empty('Nothing here yet',S.friendTab==='friends'?'Search for your friends by username.':'No pending requests at the moment.','openAddFriend','Find a Friend')}`}
function friendCard(f){let pics=S.previews[f.id]||[];return `<div class="paper friend-card"><div class="intro">${avatar(f,'mid')}<div><h3>${esc(f.display_name)}</h3><p class="muted" style="font-size:12px">@${esc(f.username)}</p></div></div>${S.friendTab==='friends'?`<div class="preview-rail">${pics.slice(0,3).map(i=>`<img src="${esc(urlItem(i))}" alt="${esc(i.name)}">`).join('')||'<span class="muted">Visit their closet</span>'}</div><div class="actions">${btn('View Closet','viewFriend',f.id,'primary','small')}${btn('Remove','removeFriend',f.friendship_id,'secondary','small')}</div>`:`<div style="margin-top:15px;display:flex;gap:8px">${S.friendTab==='incoming'?btn(ico('check')+' Accept','acceptFriend',f.friendship_id,'sage'):''}${btn(S.friendTab==='incoming'?'Reject':'Cancel',S.friendTab==='incoming'?'rejectFriend':'cancelFriend',f.friendship_id,'secondary')}</div>`}</div>`}
function pageFriend(){let c=S.friendCloset;if(!c)return empty('Friend not found','');let u=c.user,ward=c.items.filter(matches);return `<div class="page-toolbar">${btn(ico('back')+' Back to Friends','goFriends','','secondary')}</div><div class="friend-layout"><aside class="friend-profile paper">${avatar(u,'big')}<div><h2>${esc(u.display_name)}</h2><p style="margin-top:2px">@${esc(u.username)}</p><p>${esc(u.bio||'My little closet')}</p><div class="layout-row" style="justify-content:center;margin-top:15px"><span class="stat-chip">${u.items_count} pieces</span><span class="stat-chip">${u.ootds_count} visible OOTDs</span></div></div></aside><div class="friend-body"><h1>${esc(u.display_name)}’s Closet</h1><p class="muted" style="margin:8px 0 18px">Mix your styles, share inspirations.</p><div class="privacy-bar">${ico('lock')} You can only view this friend's OOTDs if <strong>every clothing owner</strong> in the outfit is you or one of your accepted friends. Restricted outfits are entirely hidden.</div><div class="pill-tabs" style="margin-bottom:16px">${btn('Wardrobe ('+c.items.length+')','friendWardrobe','',''+(S.friendTab==='wardrobe'?'primary':'secondary'))}${btn('OOTDs ('+c.ootds.length+')','friendOutfits','',''+(S.friendTab==='outfits'?'primary':'secondary'))}</div>${S.friendTab==='outfits'?c.ootds.length?`<div class="outfit-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${c.ootds.map(o=>outfitCard(o,true)).join('')}</div>`:empty('No visible OOTDs','Outfits with clothing from people you are not friends with do not appear here.'):`<div class="page-toolbar"><div class="search">${ico('search')}<input id="friend-wardrobe-search" class="input" placeholder="Search their clothes..." value="${esc(S.search)}"></div>${categoryTabs(c.items)}</div><div class="friend-closet-grid">${ward.map(i=>clothingCard(i,true)).join('')}</div>`}</div></div>`}
function borrowActions(r){let st=r.status,owner=r.is_owner;let actions=[];if(owner&&st==='pending')actions=[['Approve','approve','sage'],['Reject','reject','danger']];else if(owner&&st==='approved')actions=[['Confirm Handover','handover','primary']];else if(owner&&st==='return_requested')actions=[['Confirm Return','confirm_return','sage']];else if(!owner&&['pending','approved'].includes(st))actions=[['Cancel Request','cancel','secondary']];else if(!owner&&st==='borrowed')actions=[['Request Return','request_return','primary']];return actions.map(([label,a,k])=>btn(label,'borrowAction',r.id+'|'+a,k,'small')).join('')}
function pageBorrowing(){let tabs=[['requests','Requests'],['mine','Borrowed by Me'],['lent','Lent to Friends'],['history','History']];let found=(S.borrow||[]).filter(r=>S.borrowTab==='requests'?(r.status==='pending'||r.status==='approved'):(S.borrowTab==='mine'?r.borrower_id===S.me.id&&['borrowed','return_requested'].includes(r.status):(S.borrowTab==='lent'?r.is_owner&&['borrowed','return_requested'].includes(r.status):['returned','rejected','cancelled'].includes(r.status))));return `<div class="heading-line"><div><h1 class="tag-paper">Borrowing & Tracking</h1><p>Know where your clothes are, and share with care.</p></div></div><div class="pill-tabs" style="margin-bottom:20px">${tabs.map(([k,label])=>`<button class="pill ${S.borrowTab===k?'active':''}" data-action="borrowTab" data-id="${k}">${label}</button>`).join('')}</div>${found.length?`<div class="request-list">${found.map(r=>`<div class="request-row"><img src="${esc(r.image_path)}" alt="${esc(r.item_name)}"><div class="who"><strong>${esc(r.item_name)}</strong><p>Owner: ${esc(r.owner?.display_name)} · Borrower: ${esc(r.borrower?.display_name)}</p><p>${niceDate(r.created_at)}</p></div>${badge(r.status)}<div class="actions">${borrowActions(r)}${['cancelled','rejected','returned'].includes(r.status)?btn(ico('trash')+' Delete','deleteBorrowHistory',r.id,'ghost','small'):''}</div></div>`).join('')}</div>`:empty('All caught up',S.borrowTab==='requests'?'No incoming or outgoing requests right now.':'No items in this section.')}<div class="note sage" style="margin-top:20px">Borrowing is separate from outfit planning. Approval reserves an item; the owner confirms the physical handover before its holder changes. Returns also require owner confirmation.</div>`}
function pageNotifications(){let n=S.notifications,a=S.activity||{activity:[],borrow_logs:[]};return `<div class="heading-line"><div><h1 class="tag-paper">Notifications & Activity</h1><p>Little updates from your wardrobe circle</p></div></div><div class="pill-tabs" style="margin-bottom:18px">${btn('Notifications','notifyNotifications','',''+(S.notifyTab==='notifications'?'primary':'secondary'))}${btn('Activity & Notes','notifyActivity','',''+(S.notifyTab==='activity'?'primary':'secondary'))}${btn('Borrow Status Log','notifyBorrowLogs','',''+(S.notifyTab==='borrowlogs'?'primary':'secondary'))}</div>${S.notifyTab==='notifications'?`<form id="reminder-form" class="panel" style="display:flex;flex-wrap:wrap;gap:9px;padding:15px;margin-bottom:14px"><input name="title" class="input" placeholder="Personal reminder title" maxlength="90" required style="flex:1;min-width:150px"><input name="message" class="input" placeholder="Reminder message" maxlength="300" required style="flex:2;min-width:200px"><button type="submit" class="btn primary">${ico('plus')} Add Reminder</button></form><div class="feed-list">${n.map(x=>`<div class="feed-row ${x.read?'':'unread'}"><div class="feed-icon">${ico('bell')}</div><div class="content"><strong>${esc(x.title)}</strong><p>${esc(x.message)} · ${niceDate(x.created_at)}</p></div>${btn(x.read?'Unread':'Mark Read','markNotification',x.id,'ghost','small')}${btn(ico('trash'),'deleteNotification',x.id,'ghost','small')}</div>`).join('')||empty('No notifications','You are up to date')}</div>`:S.notifyTab==='activity'?`<div class="panel" style="padding:17px;margin-bottom:16px"><form id="journal-form" class="layout-row"><input name="note" class="input" placeholder="Write a little wardrobe journal note..." style="flex:1" maxlength="300" required><button type="submit" class="btn primary">${ico('plus')} Add Note</button></form></div><div class="feed-list">${a.activity.map(x=>`<div class="feed-row"><div class="feed-icon">${ico(x.action==='journal'?'edit':'check')}</div><div class="content"><strong>${esc(x.message)}</strong><p>${niceDate(x.created_at)}</p></div>${x.action==='journal'?`${btn(ico('edit'),'editJournal',x.id,'ghost','small')}${btn(ico('trash'),'deleteJournal',x.id,'ghost','small')}`:''}</div>`).join('')||empty('No activity','Actions and notes will appear here.')}</div>`:`<form id="borrow-log-form" class="panel" style="display:flex;gap:9px;padding:15px;margin-bottom:14px"><input name="note" class="input" placeholder="Add a personal borrowing note..." maxlength="300" required style="flex:1"><button type="submit" class="btn primary">${ico('plus')} Add Note</button></form><div class="feed-list">${a.borrow_logs.map(x=>`<div class="feed-row"><div class="feed-icon">${ico('box')}</div><div class="content"><strong>${esc(x.message)}</strong><p>${esc(x.note||'')}${x.note?' · ':''}${niceDate(x.created_at)}</p></div>${btn(ico('edit')+' Note','annotateLog',x.id,'secondary','small')}${x.action==='personal_note'?btn(ico('trash'),'deleteBorrowLog',x.id,'ghost','small'):''}</div>`).join('')||empty('No borrowing history','Loan events will appear here.')}</div>`}`}
function pageProfile(){return `<div class="heading-line"><div><h1 class="tag-paper">My Profile</h1><p>Make your closet feel like you</p></div></div><div class="panel profile-layout"><div class="profile-pic">${avatar(S.me,'big')}<strong>@${esc(S.me.username)}</strong><button class="btn secondary small" data-action="changeAvatar">${ico('camera')} Change Photo</button><input type="file" id="avatar-input" accept="image/*" hidden></div><form id="profile-form" class="profile-form"><div class="field"><label>Display Name</label><input name="display_name" class="input" value="${esc(S.me.display_name)}" required></div><div class="field"><label>Username</label><input name="username" class="input" value="${esc(S.me.username)}" required minlength="3"></div><div class="field"><label>Email</label><input name="email" type="email" class="input" value="${esc(S.me.email)}" required></div><div class="field"><label>Current Password (only if changing password)</label><input name="current_password" type="password" class="input" autocomplete="current-password"></div><div class="field"><label>New Password (optional)</label><input name="new_password" type="password" class="input" minlength="8" autocomplete="new-password"></div><div class="field"><label>About Me</label><textarea name="bio" rows="4" maxlength="280">${esc(S.me.bio||'')}</textarea></div><div class="layout-row"> <button class="btn primary" type="submit">${ico('save')} Save Changes</button>${btn(ico('logout')+' Log Out','logout','','secondary')}</div></form></div><div class="panel" style="padding:20px;margin-top:20px"><h3>Account management</h3><p class="muted" style="margin:8px 0 12px">Close this account and revoke all active sessions. You must complete any active loans first. Historical lending records remain pseudonymous.</p>${btn(ico('trash')+' Close My Account','deleteAccount','','danger')}</div>`}
function renderModal(){const m=S.modal;let inside='';if(m==='add'){inside=`<h2 class="modal-title">Add Clothing</h2><form id="clothing-form"><input type="hidden" name="request_token" value="${esc(S.uploadRequestToken||'')}"><div class="modal-grid"><div><div class="upload-zone" data-action="selectPhoto">${ico('camera',30)}<strong>Upload or Take Photo</strong><span>PNG/JPG · Maximum 8 MB</span></div><input id="clothing-file" type="file" name="file" accept="image/*" style="display:none" required><img class="upload-preview" id="uploaded-photo" style="display:none;margin-top:9px" alt="Clothing preview"><p class="muted" style="font-size:12px;margin-top:12px">Background removal runs inside our own web server. If the optional offline model is not installed, the original image is saved and clearly reported.</p></div><div style="display:grid;gap:11px"><div class="field"><label>Clothing Name *</label><input name="name" class="input" placeholder="e.g. Cable Knit Cardigan" required maxlength="100"></div><div class="field"><label>Category *</label><select name="category" required>${['Tops','Bottoms','Dresses','Outerwear','Shoes','Bags','Accessories','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Color</label><input name="color" class="input" placeholder="Cream"></div><div class="field"><label>Details</label><textarea name="details" rows="3" placeholder="Size, brand, notes..."></textarea></div></div></div><div class="modal-actions">${btn('Cancel','closeModal','','secondary')}<button type="submit" class="btn primary">${ico('save')} Save Clothing</button></div></form>`}
 if(m==='detail'||m==='edit'){let i=S.detail;inside=`<h2 class="modal-title">${m==='edit'?'Edit Clothing':'Clothing Details'}</h2><div class="modal-grid"><div><div class="paper" style="padding:15px"><img src="${esc(i.image_path)}" style="height:250px;width:100%;object-fit:contain" alt="${esc(i.name)}"></div><div style="margin-top:14px;text-align:center">${badge(i.state,i.holder)}</div><div class="muted" style="margin-top:12px;font-size:12px;text-align:center">Owned by ${esc(i.owner||'You')}${i.holder?` · Currently with ${esc(i.holder)}`:''}</div></div>${m==='edit'?`<form id="edit-clothing-form" class="profile-form"><div class="field"><label>Name</label><input class="input" name="name" value="${esc(i.name)}" required></div><div class="field"><label>Category</label><select name="category">${['Tops','Bottoms','Dresses','Outerwear','Shoes','Bags','Accessories','Other'].map(c=>`<option ${c===i.category?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Color</label><input class="input" name="color" value="${esc(i.color)}"></div><div class="field"><label>Details</label><textarea name="details" rows="3">${esc(i.details)}</textarea></div><div class="layout-row">${btn('Cancel','openClothing',i.id)}<button class="btn primary" type="submit">Save Changes</button></div></form>`:`<div style="display:grid;gap:11px;align-content:start"><h2>${esc(i.name)}</h2><div>Category: <strong>${esc(i.category)}</strong></div><div>Color: <strong>${esc(i.color)}</strong></div><p class="muted">${esc(i.details||'No notes yet')}</p><div class="divider"></div>${i.owner_id===S.me.id?`${btn(ico('plus')+' Add to OOTD','addOwnToOOTD',i.id,'soft')}${btn(ico('edit')+' Edit','editClothing',i.id,'secondary')}${btn(ico('trash')+' Delete','deleteClothing',i.id,'danger')}`:`${btn('+ Add to My OOTD','addFriendToOOTD',i.id,'soft')}${btn('Request to Borrow','requestBorrow',i.id,'primary')}`}</div>`}</div>`}
 if(m==='addFriend'){inside=`<h2 class="modal-title">Add a Friend</h2><p class="muted" style="margin-bottom:20px">Find friends by username and share your wardrobe.</p><form id="add-friend-form"><div class="field"><label>Username</label><input class="input" name="username" placeholder="e.g. may" required autofocus></div><div class="modal-actions">${btn('Cancel','closeModal')}<button type="submit" class="btn primary">Send Friend Request</button></div></form>`}
 if(m==='journal'||m==='log'){inside=`<h2 class="modal-title">${m==='journal'?'Edit Journal Note':'Add a note to this loan event'}</h2><form id="note-form"><textarea class="input" name="note" rows="4" maxlength="300" required>${esc(S.noteValue||'')}</textarea><div class="modal-actions">${btn('Cancel','closeModal')}<button type="submit" class="btn primary">Save Note</button></div></form>`}
 if(m==='outfit'){let o=S.outfitDetail;let it=o.items[S.outfitItemIndex]||null;inside=`<h2 class="modal-title">${esc(o.title)}</h2><p class="muted" style="font-size:13px;margin:-10px 0 15px">Select a piece in this outfit to see its name and original owner.</p><div class="outfit-detail-grid"><div class="outfit-detail-preview" aria-label="Outfit preview">${outfitPreview(o,true)}</div><div class="outfit-detail-pieces"><h3>Outfit Pieces</h3><p class="muted" style="font-size:13px;margin:7px 0 14px">${o.items.length} clothing stickers</p><div class="feed-list" style="max-height:300px;overflow:auto">${o.items.map((i,k)=>`<button class="feed-row" data-action="selectOutfitItem" data-id="${k}" style="text-align:left;cursor:pointer;${k===S.outfitItemIndex?'border-color:#9b7758':''}"><img src="${esc(i.image_path)}" style="width:45px;height:54px;object-fit:contain"><div class="content"><strong>${esc(i.name||'Unavailable')}</strong><p>Original owner: ${esc(i.owner_name||'Unavailable')}</p></div></button>`).join('')}</div><div class="divider"></div>${it?`<div class="note">Selected: <strong>${esc(it.name||'Unavailable')}</strong><br>Owned by ${esc(it.owner_name||'Unavailable')} (${esc(it.owner_username||'')})</div>`:''}<p class="muted" style="font-size:12px;margin:12px 0">This outfit is for planning. Clothing ownership stays with its original owner.</p>${!S.outfitIsFriend?btn(ico('edit')+' Open in Editor','editOOTD',o.id,'primary'):''}</div></div>`}
 if(m==='menu'){inside=`<h2 class="modal-title">Navigate</h2><div style="display:grid;gap:10px">${[['home','Home'],['wardrobe','My Wardrobe'],['ootd','OOTD Gallery'],['friends','Friends'],['borrowing','Borrowing'],['notifications','Notifications & Activity'],['profile','My Profile']].map(([p,n])=>`<a data-link href="/${p}" class="btn secondary">${n}</a>`).join('')}</div>`}
 return `<div class="modal-layer" data-action="backdrop"><div class="modal ${m==='outfit'?'outfit-detail-modal':''}" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Close" data-action="closeModal">×</button>${inside}</div></div>`}
function addCanvasItem(i){if(!S.editor)S.editor={id:null,title:'',items:[],selected:-1};const k=S.editor.items.length;S.editor.items.push({item_id:i.id,owner_id:i.owner_id,image_path:i.image_path,name:i.name,owner_name:i.owner,x:.14+(k%4)*.15,y:.12+(k%3)*.16,w:.36,z:k+1});S.editor.selected=k}
function pickItem(id){return [...(S.wardrobe||[]),...(S.friendCloset?.items||[]),...(S.studioFriendItems||[])].find(i=>i.id===id)}
async function doAction(a,id){switch(a){
 case'mobileMenu':S.modal='menu';render();break;case'goNotifications':navigate('/notifications');break;case'goProfile':navigate('/profile');break;case'goFriends':navigate('/friends');break;case'goOOTD':navigate('/ootd');break;
 case'authSwitch':S.authMode=S.authMode==='login'?'register':'login';render();break;
 case'demoLogin':await api('/auth/login',{method:'POST',body:{username:'taa',password:'demo12345'}});S.me=await api('/me');navigate('/home');break;
 case'logout':await api('/auth/logout',{method:'POST'});S.me=null;S.authMode='login';history.pushState({},'','/');render();break;
 case'deleteAccount':if(confirm('Permanently close your account? Active loans must be resolved first. This cannot be undone.')){await api('/me',{method:'DELETE'});S.me=null;history.pushState({},'','/');render();toast('Account closed')}break;
 case'openAdd':S.uploadRequestToken=globalThis.crypto?.randomUUID?.()||('upload-'+Date.now()+'-'+Math.random().toString(36).slice(2));S.modal='add';render();break;case'closeModal':S.modal=null;render();break;case'backdrop':S.modal=null;render();break;
 case'selectPhoto':document.querySelector('#clothing-file')?.click();break;
 case'openClothing':case'friendItem':{let item=pickItem(id);if(item){S.detail=item;S.modal='detail';render()}break}
 case'editClothing':S.detail=pickItem(id)||S.detail;S.modal='edit';render();break;
 case'deleteClothing':if(confirm('Remove this clothing item? It will remain in the lending history.')){await api(`/wardrobe/${id}`,{method:'DELETE'});S.modal=null;S.wardrobe=(await api('/wardrobe')).items;render();toast('Clothing removed')}break;
 case'filter':S.filter=id;render();break;
 case'newOOTD':S.pendingItem=null;navigate('/studio');break;
 case'editOOTD':navigate('/studio/'+id);break;
 case'showOutfit':case'showFriendOutfit':{let friend=a==='showFriendOutfit';let o=friend?S.friendCloset?.ootds?.find(v=>v.id===id):S.outfits.find(v=>v.id===id);if(o){S.outfitDetail=o;S.outfitItemIndex=0;S.outfitIsFriend=friend;S.modal='outfit';render()}break}
 case'selectOutfitItem':S.outfitItemIndex=Number(id);render();break;
 case'deleteOOTD':if(confirm('Delete this saved OOTD?')){await api(`/ootds/${id}`,{method:'DELETE'});S.outfits=(await api('/ootds')).ootds;render();toast('OOTD deleted')}break;
 case'putItem':{let i=pickItem(id);if(i){addCanvasItem(i);render()}break}
 case'studioMine':S.studioTab='mine';S.filter='All';S.search='';render();break;
 case'studioFriends':S.studioTab='friends';S.filter='All';S.search='';render();break;
 case'layerForward':if(S.editor?.selected>=0){S.editor.items[S.editor.selected].z++;render()}break;
 case'layerBackward':if(S.editor?.selected>=0){S.editor.items[S.editor.selected].z--;render()}break;
 case'removeCanvas':if(S.editor?.selected>=0){S.editor.items.splice(S.editor.selected,1);S.editor.selected=-1;render()}break;
 case'saveOOTD':{let e=S.editor;e.title=document.querySelector('#editor-title')?.value.trim()||e.title;if(!e.title){toast('Name your outfit before saving',true);break}if(!e.items.length){toast('Add clothing to the canvas',true);break}
 let body={title:e.title,items:e.items.map(({item_id,x,y,w,z})=>({item_id,x,y,w,z}))};await api('/ootds'+(e.id?'/'+e.id:''),{method:e.id?'PATCH':'POST',body});toast('OOTD saved');navigate('/ootd');break}
 case'openAddFriend':S.modal='addFriend';render();break;case'friendTab':S.friendTab=id;render();break;
 case'searchFriend':{let name=document.querySelector('#friend-search')?.value.trim();if(!name)break;let d=await api('/users/search?q='+encodeURIComponent(name));S.searchPeople=d.users;S.modal='addFriend';render();const f=document.querySelector('#add-friend-form input');if(f)f.value=name;toast(d.users.length?`${d.users.length} user(s) found. Send a request by username.`:'No users found.');break}
 case'viewFriend':S.friendTab='wardrobe';navigate('/friend/'+id);break;
 case'friendWardrobe':S.friendTab='wardrobe';S.filter='All';S.search='';render();break;case'friendOutfits':S.friendTab='outfits';render();break;
 case'acceptFriend':case'rejectFriend':case'cancelFriend':await api('/friends/'+id,{method:'PATCH',body:{action:a.replace('Friend','')}});S.friends=await api('/friends');render();toast('Friend request updated');break;
 case'removeFriend':if(confirm('Remove this friend? Their wardrobe and restricted OOTDs will no longer be visible.')){await api('/friends/'+id,{method:'DELETE'});navigate('/friends')}break;
 case'addOwnToOOTD':case'addFriendToOOTD':{let item=pickItem(id);if(!item)break;S.pendingItem=item;S.modal=null;navigate('/studio');break}
 case'requestBorrow':if(confirm('Send a request to borrow this piece?')){await api('/borrowing',{method:'POST',body:{item_id:id}});S.modal=null;toast('Borrow request sent');navigate('/borrowing')}break;
 case'viewFriendOutfit':{const o=S.friendCloset?.ootds?.find(v=>v.id===id);if(o){S.modal=null;toast(`${o.title} — clothes from: ${[...new Set(o.items.map(i=>i.owner_name))].join(', ')}`)}break}
 case'borrowTab':S.borrowTab=id;render();break;
 case'borrowAction':{let [rid,action]=id.split('|');await api('/borrowing/'+rid,{method:'PATCH',body:{action}});S.borrow=(await api('/borrowing')).requests;render();toast('Borrowing status updated')}break;
 case'deleteBorrowHistory':if(confirm('Delete this completed borrowing request and its SQL loan record?')){await api('/borrowing/'+id,{method:'DELETE'});S.borrow=(await api('/borrowing')).requests;render();toast('Completed request deleted')}break;
 case'notifyNotifications':S.notifyTab='notifications';render();break;case'notifyActivity':S.notifyTab='activity';render();break;case'notifyBorrowLogs':S.notifyTab='borrowlogs';render();break;
 case'markNotification':{let item=S.notifications.find(n=>n.id===id);await api('/notifications/'+id,{method:'PATCH',body:{read:!!item.read?false:true}});S.notifications=(await api('/notifications')).notifications;render();break}
 case'deleteNotification':await api('/notifications/'+id,{method:'DELETE'});S.notifications=(await api('/notifications')).notifications;render();break;
 case'editJournal':{let d=S.activity.activity.find(x=>x.id===id);S.noteId=id;S.noteValue=d?.note;S.modal='journal';render();break}
 case'deleteJournal':if(confirm('Delete your journal note?')){await api('/activity/'+id,{method:'DELETE'});S.activity=await api('/activity');render()}break;
 case'annotateLog':{let d=S.activity.borrow_logs.find(x=>x.id===id);S.noteId=id;S.noteValue=d?.note;S.modal='log';render();break}
 case'deleteBorrowLog':if(confirm('Delete this personal borrowing note?')){await api('/borrow-logs/'+id,{method:'DELETE'});S.activity=await api('/activity');render();toast('Note removed')}break;
 case'changeAvatar':document.querySelector('#avatar-input')?.click();break;
 default:break;
}}
document.addEventListener('click',event=>{let link=event.target.closest('[data-link]');if(link){event.preventDefault();navigate(new URL(link.href).pathname);return}let b=event.target.closest('[data-action]');if(b){const a=b.dataset.action;if(a==='backdrop'&&!event.target.classList.contains('modal-layer'))return;event.preventDefault();run(()=>doAction(a,b.dataset.id||''))}});
document.addEventListener('submit',event=>{let f=event.target;event.preventDefault();
 if(f.dataset.submitting==='true')return;
 f.dataset.submitting='true';
 const buttons=[...f.querySelectorAll('button[type="submit"]')];
 buttons.forEach(button=>{button.disabled=true;button.setAttribute('aria-busy','true');});
 run(async()=>{try{
 if(f.id==='auth-form'){
  let d=Object.fromEntries(new FormData(f));await api('/auth/'+(S.authMode==='register'?'register':'login'),{method:'POST',body:d});S.me=await api('/me');navigate('/home');toast('Welcome to your wardrobe')
 }else if(f.id==='clothing-form'){
  let data=new FormData(f);let file=document.querySelector('#clothing-file')?.files?.[0];if(!file){toast('Choose a photo first',true);return}data.set('file',file);let r=await api('/wardrobe',{method:'POST',body:data,form:true});S.modal=null;S.uploadRequestToken=null;S.wardrobe=(await api('/wardrobe')).items;render();toast(r.duplicate?'Already saved — no duplicate created.':(r.ai_processed?'Clothing added with background removed.':'Clothing added. Local AI is not connected, so the original photo was kept.'))
 }else if(f.id==='edit-clothing-form'){
  let d=Object.fromEntries(new FormData(f));await api('/wardrobe/'+S.detail.id,{method:'PATCH',body:d});S.modal=null;S.wardrobe=(await api('/wardrobe')).items;render();toast('Clothing updated')
 }else if(f.id==='add-friend-form'){
  let d=Object.fromEntries(new FormData(f));await api('/friends',{method:'POST',body:d});S.modal=null;S.friends=await api('/friends');render();toast('Friend request sent')
 }else if(f.id==='profile-form'){
  let d=Object.fromEntries(new FormData(f));await api('/me',{method:'PATCH',body:d});S.me=await api('/me');render();toast('Profile saved')
 }else if(f.id==='reminder-form'){
  await api('/notifications',{method:'POST',body:Object.fromEntries(new FormData(f))});S.notifications=(await api('/notifications')).notifications;render();toast('Reminder added')
 }else if(f.id==='borrow-log-form'){
  await api('/borrow-logs',{method:'POST',body:Object.fromEntries(new FormData(f))});S.activity=await api('/activity');render();toast('Borrowing note added')
 }else if(f.id==='journal-form'){
  await api('/activity',{method:'POST',body:Object.fromEntries(new FormData(f))});S.activity=await api('/activity');render();toast('Note added')
 }else if(f.id==='note-form'){
  let note=new FormData(f).get('note');await api((S.modal==='journal'?'/activity/':'/borrow-logs/')+S.noteId,{method:'PATCH',body:{note}});S.activity=await api('/activity');S.modal=null;render();toast('Note updated')
 }
 }finally{
  f.dataset.submitting='false';
  buttons.forEach(button=>{button.disabled=false;button.removeAttribute('aria-busy');});
 }
})});
document.addEventListener('change',event=>{let el=event.target;run(async()=>{
 if(el.id==='clothing-file'){
  let f=el.files?.[0];if(f){let image=document.querySelector('#uploaded-photo');image.src=URL.createObjectURL(f);image.style.display='block'}
 }
 if(el.id==='avatar-input'){let f=el.files?.[0];if(!f)return;let data=new FormData();data.set('file',f);await api('/me/avatar',{method:'POST',body:data,form:true});S.me=await api('/me');render();toast('Profile photo updated')}
 if(el.id==='studio-friend'){S.studioFriendId=el.value;S.studioFriendItems=el.value?(await api('/friends/'+el.value+'/closet')).items:[];S.filter='All';S.search='';render()}
 if(el.id==='library-category'){S.filter=el.value;render()}
 if(el.id==='item-size'){let i=S.editor?.items[S.editor.selected];if(i){i.w=Number(el.value)/100;render()}}
})});
document.addEventListener('input',e=>{let id=e.target.id;
 if(['wardrobe-search','friend-wardrobe-search','ootd-search','library-search'].includes(id)){
  S.search=e.target.value;
  // preserve caret/focus while updating only the card grids instead of re-rendering each keypress
  const focusId=id,position=e.target.selectionStart;render();let replacement=document.getElementById(focusId);if(replacement){replacement.focus();replacement.setSelectionRange(position,position)}
 }
 if(id==='editor-title'&&S.editor)S.editor.title=e.target.value;
});
let dragging=null;
document.addEventListener('pointerdown',e=>{
 const el=e.target.closest('.editor-object');if(!el||!S.editor)return;
 const rect=document.querySelector('#editor-canvas').getBoundingClientRect();const index=Number(el.dataset.index);const item=S.editor.items[index];if(!item)return;
 S.editor.selected=index;el.classList.add('selected');dragging={index,el,rect,x:e.clientX,y:e.clientY,startX:item.x,startY:item.y};el.setPointerCapture?.(e.pointerId);e.preventDefault();
});
document.addEventListener('pointermove',e=>{
 if(!dragging)return;const d=dragging,item=S.editor.items[d.index];item.x=Math.min(1.3,Math.max(-.35,d.startX+(e.clientX-d.x)/d.rect.width));item.y=Math.min(1.3,Math.max(-.35,d.startY+(e.clientY-d.y)/d.rect.height));d.el.style.left=(item.x*100)+'%';d.el.style.top=(item.y*100)+'%';
});
document.addEventListener('pointerup',()=>{if(dragging){dragging=null;render()}});
window.addEventListener('popstate',route);
(async()=>{try{{const flags=await api('/health');S.allowDemo=!!flags.demo_enabled}}catch{}try{S.me=await api('/me')}catch{S.me=null}if(S.me){await route()}else{render()}})();
